import{_ as a,o as t,c as e,a4 as s}from"./chunks/framework.B-wJupoK.js";const i="/assets/image-20250604154144296.Dhs9FdZx.png",l="/assets/image-20250604154712749.PDXn6hcl.png",r="/assets/image-20250604154654173.CoZBRUQD.png",p="/assets/image-20250604161153167.CBlbDlpr.png",o="/assets/image-20250604155808917.Pg170vvX.png",g="/assets/image-20250604160132698.7S5fkSHF.png",c="/assets/image-20250604160239603.BoRhY4mF.png",m="/assets/image-20250604160259889.D5pubLcs.png",d="/assets/image-20250604160336458.DOWPDht_.png",h="/assets/image-20250604160436312.Sh6F2UdP.png",b="/assets/image-20250604160620575.RbS-jST8.png",w=JSON.parse('{"title":"鸿蒙上架项目-止欲-技术分析","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙上架项目-止欲-技术分享/鸿蒙上架项目-止欲-技术分享.md","filePath":"鸿蒙开发技巧/鸿蒙上架项目-止欲-技术分享/鸿蒙上架项目-止欲-技术分享.md","lastUpdated":1749024933000,"__rawMarkdown":"# 鸿蒙上架项目-止欲-技术分析\\n\\n## 止欲介绍\\n\\n**止欲**是一款休闲类的鸿蒙元服务，希望可以通过冥想让繁杂的生活慢下来、静下来。\\n\\n![image-20250604154144296](assets/image-20250604154144296.png)\\n\\n《止欲》从立项到上架总过程差不多两个月，主要都是我们[青蓝](https://www.qinglanzhuma.cn/)的小伙伴在工作止欲抽空完成的，已经实属不易了，我们主要开发者都是00后，最年轻的开发者也是才19岁。\\n\\n立项时间是：**2025-04-08**\\n\\n![image-20250604154712749](assets/image-20250604154712749.png)\\n\\n上架时间是：**2025-06-03**\\n\\n![image-20250604154654173](assets/image-20250604154654173.png)\\n\\n止欲同时也是我们[青蓝逐码组织](https://www.qinglanzhuma.cn/)上架的第三个作品了，每个作品都是由初入职场、甚至大学还没有毕业的小伙伴高度参与！\\n\\n![image-20250604161153167](assets/image-20250604161153167.png)\\n\\n## git 日志一览\\n\\n![image-20250604155808917](assets/image-20250604155808917.png)\\n\\n## 项目技术细节\\n\\n\\n\\n### 项目架构\\n\\n```\\nSerenity/Application/\\n├── entry/                          # 主模块\\n│   ├── src/main/\\n│   │   ├── ets/                    # TypeScript源码\\n│   │   │   ├── entryability/       # 应用入口能力\\n│   │   │   ├── entryformability/   # 服务卡片能力\\n│   │   │   ├── pages/              # 页面文件\\n│   │   │   ├── view/               # UI组件\\n│   │   │   ├── utils/              # 工具类\\n│   │   │   ├── model/              # 数据模型\\n│   │   │   ├── const/              # 常量定义\\n│   │   │   └── navigationStack/    # 导航栈管理\\n│   │   └── resources/              # 资源文件\\n│   └── module.json5                # 模块配置\\n├── EntryCard/                      # 服务卡片模块\\n├── AppScope/                       # 应用级配置\\n└── oh-package.json5               # 依赖管理\\n```\\n\\n### 技术栈\\n\\n- **开发语言**: ArkTS (TypeScript)\\n- **UI 框架**: ArkUI\\n- **构建工具**: Hvigor\\n- **包管理**: ohpm\\n\\n\\n\\n\\n\\n### 核心开发套件 (Kit)\\n\\n本项目使用了多个 HarmonyOS 官方开发套件：\\n\\n| 套件名称                    | 用途          | 主要 API                        |\\n| :-------------------------- | :------------ | :------------------------------ |\\n| @kit.ArkUI                  | UI 框架和导航 | AtomicServiceNavigation, window |\\n| @kit.BasicServicesKit       | 基础服务      | BusinessError, request          |\\n| @kit.MediaLibraryKit        | 媒体库访问    | photoAccessHelper               |\\n| @kit.CoreFileKit            | 文件操作      | fileIo                          |\\n| @kit.ImageKit               | 图像处理      | image.createImageSource         |\\n| @kit.PerformanceAnalysisKit | 性能分析      | hilog                           |\\n| @kit.AbilityKit             | 应用能力      | UIAbility, abilityAccessCtrl    |\\n\\n### 开发环境要求\\n\\n- **HarmonyOS SDK**: 5.0.1(13) 或更高版本\\n- **DevEco Studio**: 5.0 或更高版本\\n- **编译目标**: HarmonyOS\\n\\n\\n\\n\\n\\n## 开发细节\\n\\n### 开始立项\\n\\n![image-20250604160132698](assets/image-20250604160132698.png)\\n\\n### 分析如何选型\\n\\n![image-20250604160239603](assets/image-20250604160239603.png)\\n\\n![image-20250604160259889](assets/image-20250604160259889.png)\\n\\n### 暴躁起来了\\n\\n![image-20250604160336458](assets/image-20250604160336458.png)\\n\\n## 成功上架\\n\\n![image-20250604160436312](assets/image-20250604160436312.png)\\n\\n## 后续计划\\n\\n1. 接入登录\\n2. 接入端云一体\\n3. 增加趣味性功能\\n4. 代码开源-分享教程\\n\\n\\n\\n\\n\\n## 总结\\n\\n[关于青蓝逐码组织](https://www.qinglanzhuma.cn/)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250604160620575](assets/image-20250604160620575.png)"}'),u={name:"鸿蒙开发技巧/鸿蒙上架项目-止欲-技术分享/鸿蒙上架项目-止欲-技术分享.md"};function _(y,n,f,k,x,q){return t(),e("div",null,[...n[0]||(n[0]=[s("",39)])])}const A=a(u,[["render",_]]);export{w as __pageData,A as default};
